    operation T32_IsVertexWeaklyColored () : Unit {
        let testCases = Most(ExampleGraphs());
        let colorings = [[0, 0, 0],
                         [3, 2, 0, 0],
                         [1, 0, 1, 2, 1],
                         [0, 0, 1, 1, 1],
